import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';
import confetti from 'canvas-confetti';
import { useAuth } from '../context/AuthContext';
import Navbar from '../components/Navbar';
import Footer from '../components/Footer';
import KibaShield from '../components/KibaShield';
import {
  IconBriefcaseFull,
  IconLock,
  IconEye,
  IconPeople,
  IconRobot,
  IconBell,
  IconCheck,
  IconX,
  IconAlert,
  IconClock,
  IconCheckCircle,
  IconXCircle
} from '../Icons';

const API = process.env.REACT_APP_API_URL || 'http://localhost:5000';

const poseForType = {
  application_received: 8,
  application_under_review: 7,
  application_shortlisted: 8,
  application_hired: 2,
  application_rejected: 3,
  consent_expiring: 6,
  consent_expired: 3,
  document_accessed: 3,
  third_party_request: 3,
  talent_pool_match: 8,
  job_closing_soon: 6,
  weekly_summary: 8,
  new_application: 8,
  new_registration: 8
};

const IconBellFilled = ({ size = 18 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <path d="M18 8A6 6 0 006 8c0 7-3 9-3 9h18s-3-2-3-9" fill="#EF4444" stroke="#EF4444" strokeWidth="1"/>
    <path d="M13.73 21a2 2 0 01-3.46 0" stroke="#fff" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
  </svg>
);

const CustomerDashboard = () => {
  const { user, token, darkMode } = useAuth();
  const [consents, setConsents] = useState([]);
  const [expiring, setExpiring] = useState([]);
  const [applications, setApplications] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [kibaPose, setKibaPose] = useState(1);
  const [kibaShield, setKibaShield] = useState('idle');
  const [withdrawing, setWithdrawing] = useState(null);
  const [activeTab, setActiveTab] = useState('overview');
  const [showNotifications, setShowNotifications] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);

  useEffect(() => {
    fetchData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const fetchData = async () => {
    try {
      const [consentsRes, expiringRes, applicationsRes, notificationsRes] = await Promise.all([
        axios.get(`${API}/api/consents/my`, { headers: { Authorization: `Bearer ${token}` } }),
        axios.get(`${API}/api/consents/expiring`, { headers: { Authorization: `Bearer ${token}` } }),
        axios.get(`${API}/api/applications/my`, { headers: { Authorization: `Bearer ${token}` } }),
        axios.get(`${API}/api/notifications/my`, { headers: { Authorization: `Bearer ${token}` } })
      ]);

      setConsents(consentsRes.data);
      setExpiring(expiringRes.data);
      setApplications(applicationsRes.data);
      setNotifications(notificationsRes.data);

      const unread = notificationsRes.data.filter(n => !n.isRead).length;
      setUnreadCount(unread);

      if (expiringRes.data.length > 0) {
        setKibaPose(6);
        setKibaShield('warning');
      } else if (unread > 0) {
        const latest = notificationsRes.data.find(n => !n.isRead);
        if (latest) {
          setKibaPose(poseForType[latest.type] || 1);
          if (latest.type === 'application_hired') {
            confetti({ particleCount: 200, spread: 100, origin: { y: 0.5 }, colors: ['#10B981', '#0EA5E9', '#F59E0B'] });
            setKibaShield('success');
          }
        }
      } else {
        setKibaPose(1);
        setKibaShield('idle');
      }
    } catch (err) {
      console.error('Dashboard fetch error:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleWithdraw = async (id) => {
    if (!window.confirm('Are you sure you want to withdraw this consent?')) return;
    setWithdrawing(id);
    try {
      await axios.put(`${API}/api/consents/withdraw/${id}`, {}, { headers: { Authorization: `Bearer ${token}` } });
      setKibaPose(5);
      setKibaShield('blue');
      fetchData();
      setTimeout(() => { setKibaPose(1); setKibaShield('idle'); }, 3000);
    } catch (err) {
      console.error('Withdraw error:', err);
    } finally {
      setWithdrawing(null);
    }
  };

  const markAllRead = async () => {
    try {
      await axios.put(`${API}/api/notifications/mark-all-read`, {}, { headers: { Authorization: `Bearer ${token}` } });
      fetchData();
    } catch (err) { console.error(err); }
  };

  const markRead = async (id) => {
    try {
      await axios.put(`${API}/api/notifications/mark-read/${id}`, {}, { headers: { Authorization: `Bearer ${token}` } });
      fetchData();
    } catch (err) { console.error(err); }
  };

  const activeConsents = consents.filter(c => c.status === 'active');
  const expiredConsents = consents.filter(c => c.status === 'expired');

  const statusConfig = {
    received: { bg: '#E0F2FE', color: '#075985', label: 'Received', Icon: IconCheck },
    under_review: { bg: '#FEF3C7', color: '#92400E', label: 'Under Review', Icon: IconClock },
    shortlisted: { bg: '#F3E8FF', color: '#6B21A8', label: 'Shortlisted', Icon: IconCheckCircle },
    hired: { bg: '#D1FAE5', color: '#065F46', label: 'Hired', Icon: IconCheckCircle },
    rejected: { bg: '#FEE2E2', color: '#991B1B', label: 'Not Selected', Icon: IconXCircle }
  };

  const notifIconForType = (type) => {
    if (type === 'application_hired') return <IconCheckCircle color="#10B981" size={20} />;
    if (type === 'application_rejected') return <IconXCircle color="#EF4444" size={20} />;
    if (type === 'application_shortlisted') return <IconCheck color="#8B5CF6" size={20} />;
    if (type === 'consent_expiring' || type === 'job_closing_soon') return <IconClock color="#F59E0B" size={20} />;
    if (type === 'document_accessed') return <IconEye color="#F59E0B" size={20} />;
    if (type === 'third_party_request') return <IconAlert color="#EF4444" size={20} />;
    if (type === 'talent_pool_match') return <IconBriefcaseFull color="#0EA5E9" size={20} />;
    return <IconBell color="#0EA5E9" size={20} />;
  };

  const card = {
    background: darkMode ? '#1E293B' : '#fff',
    borderRadius: '16px',
    padding: '20px',
    boxShadow: '0 4px 24px rgba(30,58,95,0.08)'
  };

  const tabStyle = (active) => ({
    padding: '9px 16px',
    borderRadius: '10px',
    border: 'none',
    fontWeight: 700,
    fontSize: '13px',
    cursor: 'pointer',
    fontFamily: 'Inter, sans-serif',
    background: active ? '#1E3A5F' : 'transparent',
    color: active ? '#fff' : '#64748B',
    transition: 'all 0.2s',
    whiteSpace: 'nowrap'
  });

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column', background: darkMode ? '#0F172A' : '#F8FAFC' }}>
      <Navbar />
      <div style={{ flex: 1, padding: '24px 16px', maxWidth: '1200px', margin: '0 auto', width: '100%', boxSizing: 'border-box' }}>

        {expiring.length > 0 && (
          <div style={{ background: '#FEF3C7', border: '1px solid #FDE68A', borderRadius: '14px', padding: '12px 16px', marginBottom: '20px', display: 'flex', alignItems: 'center', gap: '10px' }}>
            <IconAlert color="#92400E" size={18} />
            <span style={{ color: '#92400E', fontWeight: 600, fontSize: '13px' }}>
              {expiring.length} consent{expiring.length > 1 ? 's are' : ' is'} expiring within 24 hours. Review your consent settings soon.
            </span>
          </div>
        )}

        <div style={{ display: 'flex', gap: '32px', alignItems: 'flex-start', flexWrap: 'wrap' }}>

          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '12px', minWidth: '220px' }}>
            <KibaShield pose={kibaPose} shieldState={kibaShield} />
            <p style={{ color: '#64748B', fontSize: '13px', textAlign: 'center', fontWeight: 500 }}>
              Hello, {user?.fullName?.split(' ')[0]}!
            </p>
            {user?.applicantId && (
              <div style={{ background: '#1E3A5F', border: '1.5px solid #0EA5E9', color: '#0EA5E9', padding: '6px 14px', borderRadius: '999px', fontSize: '12px', fontWeight: 700, fontFamily: 'Roboto Mono, monospace' }}>
                {user.applicantId}
              </div>
            )}
          </div>

          <div style={{ flex: 1, minWidth: '280px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '12px', marginBottom: '20px' }}>
              <div>
                <h1 style={{ fontSize: '24px', fontWeight: 800, color: darkMode ? '#F1F5F9' : '#1E3A5F', marginBottom: '2px' }}>My Dashboard</h1>
                <p style={{ color: '#64748B', fontSize: '13px' }}>Manage your applications, consents and data access</p>
              </div>
              <button
                onClick={() => setShowNotifications(!showNotifications)}
                style={{ position: 'relative', background: darkMode ? '#1E293B' : '#fff', border: `1.5px solid ${unreadCount > 0 ? '#EF4444' : '#E2E8F0'}`, borderRadius: '12px', padding: '10px 16px', cursor: 'pointer', fontFamily: 'Inter, sans-serif', display: 'flex', alignItems: 'center', gap: '8px', fontWeight: 600, fontSize: '13px', color: darkMode ? '#F1F5F9' : '#1E293B', transition: 'all 0.2s' }}
              >
                {unreadCount > 0 ? <IconBellFilled size={18} /> : <IconBell color="#64748B" size={18} />}
                Notifications
                {unreadCount > 0 && (
                  <span style={{ position: 'absolute', top: '-8px', right: '-8px', background: '#EF4444', color: '#fff', borderRadius: '999px', minWidth: '20px', height: '20px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '11px', fontWeight: 800, padding: '0 4px' }}>
                    {unreadCount}
                  </span>
                )}
              </button>
            </div>

            {showNotifications && (
              <div style={{ ...card, marginBottom: '20px', maxHeight: '420px', overflowY: 'auto' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '14px' }}>
                  <h3 style={{ fontSize: '15px', fontWeight: 700, color: darkMode ? '#F1F5F9' : '#1E3A5F', display: 'flex', alignItems: 'center', gap: '8px' }}>
                    <IconBell color="#0EA5E9" size={16} />
                    Notifications
                  </h3>
                  {unreadCount > 0 && (
                    <button onClick={markAllRead} style={{ background: 'none', border: 'none', color: '#0EA5E9', fontSize: '13px', fontWeight: 600, cursor: 'pointer', fontFamily: 'Inter, sans-serif', display: 'flex', alignItems: 'center', gap: '5px' }}>
                      <IconCheck color="#0EA5E9" size={14} />
                      Mark all read
                    </button>
                  )}
                </div>
                {notifications.length === 0 ? (
                  <div style={{ textAlign: 'center', padding: '24px 0' }}>
                    <IconBell color="#94A3B8" size={32} />
                    <p style={{ color: '#64748B', fontSize: '14px', marginTop: '8px' }}>No notifications yet. Apply for jobs to get started.</p>
                  </div>
                ) : (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                    {notifications.map(notif => (
                      <div key={notif._id} onClick={() => markRead(notif._id)}
                        style={{ background: notif.isRead ? (darkMode ? '#0F172A' : '#F8FAFC') : (darkMode ? '#1E3A5F' : '#EFF6FF'), borderRadius: '12px', padding: '14px', cursor: 'pointer', border: notif.isRead ? `1px solid ${darkMode ? '#334155' : '#E2E8F0'}` : '1px solid #BFDBFE', transition: 'all 0.2s' }}>
                        <div style={{ display: 'flex', gap: '10px', alignItems: 'flex-start' }}>
                          <div style={{ flexShrink: 0, marginTop: '2px' }}>
                            {notifIconForType(notif.type)}
                          </div>
                          <div style={{ flex: 1 }}>
                            <p style={{ fontWeight: 700, fontSize: '13px', color: darkMode ? '#F1F5F9' : '#1E293B', marginBottom: '3px' }}>{notif.title}</p>
                            <p style={{ fontSize: '12px', color: '#64748B', lineHeight: 1.6 }}>{notif.message}</p>
                            <p style={{ fontSize: '11px', color: '#94A3B8', marginTop: '4px', fontFamily: 'Roboto Mono, monospace' }}>{new Date(notif.createdAt).toLocaleString()}</p>
                          </div>
                          {!notif.isRead && (
                            <div style={{ width: '8px', height: '8px', borderRadius: '50%', background: '#0EA5E9', flexShrink: 0, marginTop: '4px' }} />
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(130px, 1fr))', gap: '12px', marginBottom: '20px' }}>
              {[
                {
                  label: 'Applications', value: applications.length, color: '#1E3A5F', Icon: IconBriefcaseFull,
                  onClick: () => { setActiveTab('applications'); setKibaPose(8); setKibaShield('idle'); }
                },
                {
                  label: 'Active Consents', value: activeConsents.length, color: '#10B981', Icon: IconLock,
                  onClick: () => { setActiveTab('consents'); setKibaPose(1); setKibaShield('idle'); }
                },
                {
                  label: 'Expired', value: expiredConsents.length, color: '#EF4444', Icon: IconXCircle,
                  onClick: () => { setActiveTab('consents'); setKibaPose(3); setKibaShield('warning'); setTimeout(() => { setKibaPose(1); setKibaShield('idle'); }, 2000); }
                },
                {
                  label: 'Expiring Soon', value: expiring.length, color: '#F59E0B', Icon: IconClock,
                  onClick: () => { setActiveTab('consents'); setKibaPose(6); setKibaShield('warning'); setTimeout(() => { setKibaPose(1); setKibaShield('idle'); }, 2000); }
                }
              ].map(stat => (
                <button key={stat.label} onClick={stat.onClick}
                  style={{ ...card, textAlign: 'center', padding: '16px', cursor: 'pointer', border: 'none', transition: 'transform 0.15s' }}
                  onMouseDown={e => e.currentTarget.style.transform = 'scale(0.97)'}
                  onMouseUp={e => e.currentTarget.style.transform = 'scale(1)'}
                >
                  <div style={{ display: 'flex', justifyContent: 'center', marginBottom: '6px' }}>
                    <stat.Icon color={stat.color} size={20} />
                  </div>
                  <div style={{ fontSize: '30px', fontWeight: 800, color: stat.color, fontFamily: 'Roboto Mono, monospace' }}>{stat.value}</div>
                  <div style={{ fontSize: '11px', color: '#64748B', fontWeight: 600, marginTop: '4px', textTransform: 'uppercase', letterSpacing: '0.5px' }}>{stat.label}</div>
                </button>
              ))}
            </div>

            <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap', marginBottom: '20px' }}>
              {[
                { to: '/', label: 'Browse Jobs', Icon: IconBriefcaseFull, bg: '#1E3A5F' },
                { to: '/give-consent', label: 'Give Consent', Icon: IconLock, bg: '#0EA5E9' },
                { to: '/access-logs', label: 'Access Logs', Icon: IconEye, bg: '#10B981' },
                { to: '/talent-pool', label: 'Talent Pool', Icon: IconPeople, bg: '#F59E0B' },
                { to: '/chat', label: 'Ask Kiba', Icon: IconRobot, bg: '#8B5CF6' }
              ].map(btn => (
                <Link key={btn.to} to={btn.to} style={{ padding: '10px 18px', background: btn.bg, color: '#fff', borderRadius: '10px', textDecoration: 'none', fontWeight: 700, fontSize: '13px', display: 'flex', alignItems: 'center', gap: '7px', boxShadow: '0 2px 8px rgba(0,0,0,0.1)' }}>
                  <btn.Icon color="#fff" size={15} />
                  {btn.label}
                </Link>
              ))}
            </div>

            <div style={{ display: 'flex', gap: '8px', marginBottom: '16px', flexWrap: 'wrap' }}>
              {['overview', 'applications', 'consents'].map(t => (
                <button key={t} style={tabStyle(activeTab === t)} onClick={() => setActiveTab(t)}>
                  {t.charAt(0).toUpperCase() + t.slice(1)}
                </button>
              ))}
            </div>

            {activeTab === 'overview' && (
              <div style={card}>
                <h3 style={{ fontSize: '15px', fontWeight: 700, color: darkMode ? '#F1F5F9' : '#1E3A5F', marginBottom: '14px', display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <IconBell color="#0EA5E9" size={16} />
                  Recent Activity
                </h3>
                {loading ? (
                  <p style={{ color: '#64748B', fontSize: '14px' }}>Loading your activity...</p>
                ) : notifications.length === 0 && applications.length === 0 ? (
                  <div style={{ textAlign: 'center', padding: '28px 0' }}>
                    <IconRobot color="#94A3B8" size={40} />
                    <p style={{ color: '#64748B', fontSize: '14px', marginTop: '12px' }}>No activity yet. Browse jobs and submit your first application to get started.</p>
                    <Link to="/" style={{ display: 'inline-flex', alignItems: 'center', gap: '6px', marginTop: '16px', padding: '12px 24px', background: '#1E3A5F', color: '#fff', borderRadius: '10px', textDecoration: 'none', fontWeight: 700, fontSize: '14px' }}>
                      <IconBriefcaseFull color="#fff" size={16} />
                      Browse Jobs
                    </Link>
                  </div>
                ) : (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                    {notifications.slice(0, 5).map(notif => (
                      <div key={notif._id} style={{ display: 'flex', gap: '10px', alignItems: 'flex-start', background: darkMode ? '#0F172A' : '#F8FAFC', borderRadius: '10px', padding: '12px' }}>
                        <div style={{ flexShrink: 0 }}>{notifIconForType(notif.type)}</div>
                        <div>
                          <p style={{ fontWeight: 600, fontSize: '13px', color: darkMode ? '#F1F5F9' : '#1E293B', marginBottom: '2px' }}>{notif.title}</p>
                          <p style={{ fontSize: '12px', color: '#64748B', lineHeight: 1.5 }}>{notif.message}</p>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}

            {activeTab === 'applications' && (
              <div style={card}>
                <h3 style={{ fontSize: '15px', fontWeight: 700, color: darkMode ? '#F1F5F9' : '#1E3A5F', marginBottom: '14px', display: 'flex', alignItems: 'center', gap: '8px' }}>
                  <IconBriefcaseFull color="#0EA5E9" size={16} />
                  My Applications ({applications.length})
                </h3>
                {applications.length === 0 ? (
                  <div style={{ textAlign: 'center', padding: '28px 0' }}>
                    <IconBriefcaseFull color="#94A3B8" size={40} />
                    <p style={{ color: '#64748B', fontSize: '14px', marginTop: '12px' }}>No applications yet. Browse jobs to apply.</p>
                    <Link to="/" style={{ display: 'inline-flex', alignItems: 'center', gap: '6px', marginTop: '16px', padding: '12px 24px', background: '#1E3A5F', color: '#fff', borderRadius: '10px', textDecoration: 'none', fontWeight: 700, fontSize: '14px' }}>
                      <IconBriefcaseFull color="#fff" size={16} />
                      Browse Jobs
                    </Link>
                  </div>
                ) : (
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                    {applications.map(app => {
                      const config = statusConfig[app.status] || statusConfig.received;
                      return (
                        <div key={app._id} style={{ background: darkMode ? '#0F172A' : '#F8FAFC', borderRadius: '12px', padding: '16px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '12px' }}>
                          <div>
                            <p style={{ fontWeight: 700, fontSize: '15px', color: darkMode ? '#F1F5F9' : '#1E293B', marginBottom: '3px' }}>{app.job?.title}</p>
                            <p style={{ fontSize: '13px', color: '#0EA5E9', fontWeight: 600, marginBottom: '3px' }}>{app.company?.name}</p>
                            <p style={{ fontSize: '12px', color: '#64748B' }}>Applied {new Date(app.createdAt).toLocaleDateString()}</p>
                            {app.statusMessage && (
                              <p style={{ fontSize: '12px', color: '#64748B', marginTop: '4px', fontStyle: 'italic' }}>{app.statusMessage}</p>
                            )}
                          </div>
                          <div style={{ display: 'flex', alignItems: 'center', gap: '6px', padding: '6px 12px', borderRadius: '999px', background: config.bg }}>
                            <config.Icon color={config.color} size={14} />
                            <span style={{ fontSize: '12px', fontWeight: 700, color: config.color }}>{config.label}</span>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            )}

            {activeTab === 'consents' && (
              <div>
                <div style={{ ...card, marginBottom: '16px' }}>
                  <h3 style={{ fontSize: '15px', fontWeight: 700, color: darkMode ? '#F1F5F9' : '#1E3A5F', marginBottom: '14px', display: 'flex', alignItems: 'center', gap: '8px' }}>
                    <IconLock color="#0EA5E9" size={16} />
                    Active Consents ({activeConsents.length})
                  </h3>
                  {activeConsents.length === 0 ? (
                    <div style={{ textAlign: 'center', padding: '20px 0' }}>
                      <IconLock color="#94A3B8" size={36} />
                      <p style={{ color: '#64748B', fontSize: '14px', marginTop: '10px' }}>No active consents. Apply for a job to create consent rules.</p>
                    </div>
                  ) : (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                      {activeConsents.map(c => (
                        <div key={c._id} style={{ background: darkMode ? '#0F172A' : '#F8FAFC', borderRadius: '12px', padding: '16px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '12px' }}>
                          <div>
                            <p style={{ fontWeight: 700, fontSize: '14px', color: darkMode ? '#F1F5F9' : '#1E293B', marginBottom: '4px' }}>{c.purpose}</p>
                            <div style={{ display: 'flex', alignItems: 'center', gap: '6px', marginBottom: '6px' }}>
                              <IconClock color="#F59E0B" size={12} />
                              <p style={{ fontSize: '12px', color: '#64748B', margin: 0 }}>Expires: {new Date(c.expiresAt).toLocaleString()}</p>
                            </div>
                            <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap' }}>
                              {c.dataCategories.map(d => (
                                <span key={d} style={{ background: '#E0F2FE', color: '#075985', fontSize: '11px', fontWeight: 700, padding: '2px 8px', borderRadius: '999px' }}>{d}</span>
                              ))}
                            </div>
                          </div>
                          <button
                            onClick={() => handleWithdraw(c._id)}
                            disabled={withdrawing === c._id}
                            style={{ padding: '9px 16px', background: 'rgba(239,68,68,0.1)', color: '#EF4444', border: '1.5px solid #EF4444', borderRadius: '10px', fontWeight: 700, fontSize: '12px', cursor: 'pointer', fontFamily: 'Inter, sans-serif', display: 'flex', alignItems: 'center', gap: '6px', opacity: withdrawing === c._id ? 0.7 : 1 }}
                          >
                            <IconX color="#EF4444" size={13} />
                            {withdrawing === c._id ? 'Withdrawing...' : 'Withdraw'}
                          </button>
                        </div>
                      ))}
                    </div>
                  )}
                </div>

                {expiredConsents.length > 0 && (
                  <div style={card}>
                    <h3 style={{ fontSize: '15px', fontWeight: 700, color: darkMode ? '#F1F5F9' : '#1E3A5F', marginBottom: '14px', display: 'flex', alignItems: 'center', gap: '8px' }}>
                      <IconXCircle color="#EF4444" size={16} />
                      Expired Consents ({expiredConsents.length})
                    </h3>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                      {expiredConsents.map(c => (
                        <div key={c._id} style={{ background: darkMode ? '#0F172A' : '#FEF2F2', borderRadius: '10px', padding: '12px 16px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '8px' }}>
                          <div>
                            <p style={{ fontWeight: 600, fontSize: '13px', color: darkMode ? '#F1F5F9' : '#1E293B' }}>{c.purpose}</p>
                            <p style={{ fontSize: '11px', color: '#64748B' }}>Expired: {new Date(c.expiresAt).toLocaleString()}</p>
                          </div>
                          <div style={{ display: 'flex', alignItems: 'center', gap: '5px', padding: '3px 10px', borderRadius: '999px', background: '#FEE2E2' }}>
                            <IconXCircle color="#991B1B" size={12} />
                            <span style={{ fontSize: '11px', fontWeight: 700, color: '#991B1B' }}>EXPIRED</span>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default CustomerDashboard;
